from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=[[grid[i][j]==0 for j in range(w)] for i in range(h)]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                top,bot,lft,rgt=min(rs),max(rs),min(cs),max(cs)
                rings={}
                for a,b in comp:
                    r=min(a-top,bot-a,b-lft,rgt-b)
                    rings.setdefault(r,set()).add(grid[a][b])
                m=max(rings)
                cmap={c:rings[m-r].pop() for r in rings for c in rings[r]}
                for a,b in comp:
                    out[a][b]=cmap[grid[a][b]]
