def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=[[grid[i][j]==0 for j in range(w)] for i in range(h)]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb))
                bb={}
                for a,b in comp:
                    c=grid[a][b]
                    s=bb.setdefault(c,[a,b,a,b])
                    s[0]=min(s[0],a); s[1]=min(s[1],b); s[2]=max(s[2],a); s[3]=max(s[3],b)
                def depth(c):
                    t,l,b,r=bb[c]
                    return sum(1 for o in bb if o!=c and bb[o][0]<=t and bb[o][1]<=l and bb[o][2]>=b and bb[o][3]>=r)
                m=max(depth(c) for c in bb)
                cmap={c: next(o for o in bb if depth(o)==m-depth(c)) for c in bb}
                for a,b in comp:
                    out[a][b]=cmap[grid[a][b]]
    return out
