def color_bboxes(grid, comp):
    """Within one component, each color's bbox [top,left,bottom,right] and its cells."""
    bb={}; cells={}
    for a,b in comp:
        c=grid[a][b]
        s=bb.setdefault(c,[a,b,a,b])
        s[0]=min(s[0],a); s[1]=min(s[1],b); s[2]=max(s[2],a); s[3]=max(s[3],b)
        cells.setdefault(c,[]).append((a,b))
    return bb,cells

def containment_depth(bb, c):
    """How many other colors' bboxes contain color c's bbox."""
    t,l,b,r=bb[c]
    return sum(1 for o in bb if o!=c and bb[o][0]<=t and bb[o][1]<=l and bb[o][2]>=b and bb[o][3]>=r)

def nest_recolor(grid):
    """In each connected shape, reverse the color stack by nesting depth: outermost takes the innermost color, and so on."""
    out=[row[:] for row in grid]
    for comp in components(grid):
